import{_ as e}from"./chunks/printers.BumrHqVu.js";import{_ as r,o,c as n,a2 as a}from"./chunks/framework.DSc8fo6x.js";const u=JSON.parse('{"title":"Receipt and label printer","description":"","frontmatter":{},"headers":[],"relativePath":"en/printerler.md","filePath":"en/printerler.md"}'),i={name:"en/printerler.md"};function l(s,t,d,h,p,c){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="receipt-and-label-printer" tabindex="-1">Receipt and label printer <a class="header-anchor" href="#receipt-and-label-printer" aria-label="Permalink to &quot;Receipt and label printer&quot;">​</a></h1><p>One thermal printer (e.g. <strong>Xprinter XP-365B</strong>) can print both receipts and barcode labels.</p><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Connecting&quot;">​</a></h2><ol><li>Connect the printer by USB and install its <strong>Windows driver</strong> (the disc in the box or the manufacturer&#39;s website). It must appear in the Windows &quot;Printers&quot; list.</li><li>Kassa → <strong>Settings → Printers</strong>: <ul><li><strong>Receipt printer</strong> and <strong>Label (barcode) printer</strong> — choose the device from the list (it can be the same device);</li><li><strong>Label size</strong> (in the Sales and printing card) — the size of the label on the roll (e.g. 40×30);</li><li>optionally: <strong>Print the receipt automatically after a sale</strong>, <strong>Open the cash drawer on cash payment</strong>.</li></ul></li><li><strong>Save</strong> → <strong>Test receipt</strong> and <strong>Test label</strong>.</li><li>Scan the barcode of the test label — you should hear a &quot;beep&quot;.</li></ol><p><img src="'+e+'" alt="Printers"></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li>If a printer is selected, receipts and labels go <strong>directly, without a print dialog</strong>.</li><li>If no printer is selected (&quot;Print dialog&quot;), the Windows print dialog opens every time; it works with any printer.</li><li>If the printer is off or out of paper, an error appears and <strong>&quot;Use print dialog&quot;</strong> is offered. The receipt is not lost.</li></ul><h2 id="problemler" tabindex="-1">Problems <a class="header-anchor" href="#problemler" aria-label="Permalink to &quot;Problems {#problemler}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What to do</th></tr></thead><tbody><tr><td>&quot;Selected printer not found&quot;</td><td>Is the printer connected and switched on? Select it again in Settings.</td></tr><tr><td>A label is split across two labels / blank space is left</td><td>&quot;Label size&quot; must match the roll. Calibrate the printer&#39;s sensor (Xprinter: hold the FEED button while switching it on).</td></tr><tr><td>Barcode does not scan</td><td>Clean the thermal head; on a 30×20 label the barcode is small — 40×30 works better.</td></tr><tr><td>Cash drawer does not open</td><td>The drawer must be connected to the RJ11 port of the receipt printer (some label printers don&#39;t have this port). Try the &quot;Open drawer&quot; test.</td></tr></tbody></table>',9)])])}const m=r(i,[["render",l]]);export{u as __pageData,m as default};
